CREATE TABLE IF NOT EXISTS "areas" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- URL segment such as north-riverside. Stable, because it is what search engines have indexed and what links point at.
	"slug" VARCHAR(120) NOT NULL UNIQUE,
	-- Display name of the neighbourhood, district or town.
	"name" VARCHAR(160) NOT NULL,
	-- city | district | neighbourhood | postcode_sector. One table with a kind rather than three tables, because the hierarchy is the same shape at every level.
	"area_kind" VARCHAR(24) NOT NULL DEFAULT 'neighbourhood',
	-- Containing area. Null at the top of the tree. Self-referencing so a neighbourhood rolls up to a district and a district to a city without a fixed column per level.
	"parent_area_id" BIGINT,
	-- Approximate centre, used to default a map view when a search names an area rather than an address.
	"centre_latitude" NUMERIC(9,6),
	-- Approximate centre longitude.
	"centre_longitude" NUMERIC(9,6),
	-- Median achieved price in minor units, recomputed nightly. Cached because it appears on every area page and is far too expensive to derive per request.
	"median_price_minor" BIGINT,
	-- ISO 4217 currency the median is expressed in.
	"currency_code" CHAR(3),
	-- Editorial copy about the area. The reason area pages rank at all, and the reason areas are rows rather than a string on the property.
	"description" TEXT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "areas" IS 'The geography people actually search by. Modelled as a tree of rows so that a search for a city can include its neighbourhoods, and so area pages have somewhere to hang editorial content and statistics.';
COMMENT ON COLUMN "areas"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "areas"."slug" IS 'URL segment such as north-riverside. Stable, because it is what search engines have indexed and what links point at.';
COMMENT ON COLUMN "areas"."name" IS 'Display name of the neighbourhood, district or town.';
COMMENT ON COLUMN "areas"."area_kind" IS 'city | district | neighbourhood | postcode_sector. One table with a kind rather than three tables, because the hierarchy is the same shape at every level.';
COMMENT ON COLUMN "areas"."parent_area_id" IS 'Containing area. Null at the top of the tree. Self-referencing so a neighbourhood rolls up to a district and a district to a city without a fixed column per level.';
COMMENT ON COLUMN "areas"."centre_latitude" IS 'Approximate centre, used to default a map view when a search names an area rather than an address.';
COMMENT ON COLUMN "areas"."centre_longitude" IS 'Approximate centre longitude.';
COMMENT ON COLUMN "areas"."median_price_minor" IS 'Median achieved price in minor units, recomputed nightly. Cached because it appears on every area page and is far too expensive to derive per request.';
COMMENT ON COLUMN "areas"."currency_code" IS 'ISO 4217 currency the median is expressed in.';
COMMENT ON COLUMN "areas"."description" IS 'Editorial copy about the area. The reason area pages rank at all, and the reason areas are rows rather than a string on the property.';

CREATE INDEX "idx_areas_parent_kind"
ON "areas" ("parent_area_id", "area_kind");

CREATE TABLE IF NOT EXISTS "agencies" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- URL segment for the agency profile page.
	"slug" VARCHAR(120) NOT NULL UNIQUE,
	-- Trading name as it appears on the board outside the property.
	"name" VARCHAR(200) NOT NULL,
	-- Regulator or company registration number. Null for the small independents that predate registration requirements.
	"registration_number" VARCHAR(64),
	-- Office address that enquiries are forwarded to when no specific agent is set.
	"email" VARCHAR(320) NOT NULL,
	-- Office number shown on listings.
	"phone" VARCHAR(32),
	-- Street address of the branch.
	"address_line" VARCHAR(250),
	-- Area the branch operates from, which drives the local-agent module on area pages.
	"area_id" BIGINT,
	-- standard | featured | premium. Decides listing quotas and whether the agency listings can be promoted in results.
	"subscription_tier" VARCHAR(24) NOT NULL DEFAULT 'standard',
	-- Maximum concurrent live listings under the current contract. Null means unmetered.
	"listing_quota" INTEGER,
	-- Suspended agencies keep their rows because their historical listings, offers and viewings still resolve.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- When the agency joined the portal.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "agencies" IS 'The paying customer. Everything commercial — quotas, promotion, billing tier — attaches here rather than to individual agents, because agents change employer and the contract does not follow them.';
COMMENT ON COLUMN "agencies"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "agencies"."slug" IS 'URL segment for the agency profile page.';
COMMENT ON COLUMN "agencies"."name" IS 'Trading name as it appears on the board outside the property.';
COMMENT ON COLUMN "agencies"."registration_number" IS 'Regulator or company registration number. Null for the small independents that predate registration requirements.';
COMMENT ON COLUMN "agencies"."email" IS 'Office address that enquiries are forwarded to when no specific agent is set.';
COMMENT ON COLUMN "agencies"."phone" IS 'Office number shown on listings.';
COMMENT ON COLUMN "agencies"."address_line" IS 'Street address of the branch.';
COMMENT ON COLUMN "agencies"."area_id" IS 'Area the branch operates from, which drives the local-agent module on area pages.';
COMMENT ON COLUMN "agencies"."subscription_tier" IS 'standard | featured | premium. Decides listing quotas and whether the agency listings can be promoted in results.';
COMMENT ON COLUMN "agencies"."listing_quota" IS 'Maximum concurrent live listings under the current contract. Null means unmetered.';
COMMENT ON COLUMN "agencies"."is_active" IS 'Suspended agencies keep their rows because their historical listings, offers and viewings still resolve.';
COMMENT ON COLUMN "agencies"."created_at" IS 'When the agency joined the portal.';

CREATE TABLE IF NOT EXISTS "agents" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Employing branch. An agent who moves gets a new row rather than an edited one, so past listings keep pointing at the right office.
	"agency_id" BIGINT NOT NULL,
	-- Name shown on the listing and in enquiry emails.
	"full_name" VARCHAR(200) NOT NULL,
	-- Login identity and the address enquiries are routed to.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Direct or mobile number displayed on listings the agent owns.
	"phone" VARCHAR(32),
	-- Personal licence or registration number where the jurisdiction requires one.
	"licence_number" VARCHAR(64),
	-- Portrait shown beside listings. Enquiry rates are visibly different with and without it, which is why it is a first-class column.
	"photo_url" VARCHAR(500),
	-- Short profile for the agent page.
	"bio" TEXT,
	-- Departed agents are deactivated rather than deleted; their listings, viewings and offers all reference them.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- When the agent account was created.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "agents" IS 'The person a buyer actually talks to. Separate from the agency because enquiries, viewings and offers are routed to a human, and performance is measured per human.';
COMMENT ON COLUMN "agents"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "agents"."agency_id" IS 'Employing branch. An agent who moves gets a new row rather than an edited one, so past listings keep pointing at the right office.';
COMMENT ON COLUMN "agents"."full_name" IS 'Name shown on the listing and in enquiry emails.';
COMMENT ON COLUMN "agents"."email" IS 'Login identity and the address enquiries are routed to.';
COMMENT ON COLUMN "agents"."phone" IS 'Direct or mobile number displayed on listings the agent owns.';
COMMENT ON COLUMN "agents"."licence_number" IS 'Personal licence or registration number where the jurisdiction requires one.';
COMMENT ON COLUMN "agents"."photo_url" IS 'Portrait shown beside listings. Enquiry rates are visibly different with and without it, which is why it is a first-class column.';
COMMENT ON COLUMN "agents"."bio" IS 'Short profile for the agent page.';
COMMENT ON COLUMN "agents"."is_active" IS 'Departed agents are deactivated rather than deleted; their listings, viewings and offers all reference them.';
COMMENT ON COLUMN "agents"."created_at" IS 'When the agent account was created.';

CREATE INDEX "idx_agents_agency_active"
ON "agents" ("agency_id", "is_active");

CREATE TABLE IF NOT EXISTS "properties" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Internal reference that survives every listing. Two agencies marketing the same flat two years apart both resolve to this row.
	"property_reference" VARCHAR(32) NOT NULL UNIQUE,
	-- Street address. Displayed in full only once a listing chooses to expose it.
	"address_line1" VARCHAR(200) NOT NULL,
	-- Flat or unit designation, which is what distinguishes twelve properties sharing a street address.
	"address_line2" VARCHAR(200),
	-- Neighbourhood the property sits in. Null only while an import is awaiting geocoding.
	"area_id" BIGINT,
	-- Postal code, the most common search input after a place name.
	"postcode" VARCHAR(16),
	-- ISO 3166-1 alpha-2. Decides tenure vocabulary, measurement units and legal disclosures.
	"country_code" CHAR(2) NOT NULL,
	-- Exact latitude. Listings may choose to show an approximate pin instead, but the true point belongs to the property.
	"latitude" NUMERIC(9,6),
	-- Exact longitude.
	"longitude" NUMERIC(9,6),
	-- house | apartment | studio | townhouse | land | commercial. A physical classification, unlike the listing which is a commercial act.
	"property_type" VARCHAR(32) NOT NULL,
	-- Bedroom count. Null for land and most commercial units, which is why it is not mandatory.
	"bedrooms" SMALLINT,
	-- Bathroom count, allowing halves, because a half bath is a real and advertised thing.
	"bathrooms" NUMERIC(3,1),
	-- Internal floor area in square metres. Stored in one unit and converted for display, so that sorting by size is not a per-country branch.
	"floor_area_sqm" NUMERIC(10,2),
	-- Land area in square metres. Null for apartments.
	"plot_area_sqm" NUMERIC(12,2),
	-- Construction year. Null when unknown, which is common for older stock.
	"year_built" SMALLINT,
	-- freehold | leasehold | commonhold | share_of_freehold. A property-level legal fact that outlives any particular sale.
	"tenure" VARCHAR(24),
	-- Energy performance grade. Mandatory to publish in several jurisdictions, which is why it sits on the property and not the listing.
	"energy_rating" VARCHAR(8),
	-- When the property first entered the portal.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "properties" IS 'The building, which exists whether or not it is for sale. Keeping it separate from listings is the decision the whole schema rests on: physical facts change rarely, commercial campaigns come and go repeatedly.';
COMMENT ON COLUMN "properties"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "properties"."property_reference" IS 'Internal reference that survives every listing. Two agencies marketing the same flat two years apart both resolve to this row.';
COMMENT ON COLUMN "properties"."address_line1" IS 'Street address. Displayed in full only once a listing chooses to expose it.';
COMMENT ON COLUMN "properties"."address_line2" IS 'Flat or unit designation, which is what distinguishes twelve properties sharing a street address.';
COMMENT ON COLUMN "properties"."area_id" IS 'Neighbourhood the property sits in. Null only while an import is awaiting geocoding.';
COMMENT ON COLUMN "properties"."postcode" IS 'Postal code, the most common search input after a place name.';
COMMENT ON COLUMN "properties"."country_code" IS 'ISO 3166-1 alpha-2. Decides tenure vocabulary, measurement units and legal disclosures.';
COMMENT ON COLUMN "properties"."latitude" IS 'Exact latitude. Listings may choose to show an approximate pin instead, but the true point belongs to the property.';
COMMENT ON COLUMN "properties"."longitude" IS 'Exact longitude.';
COMMENT ON COLUMN "properties"."property_type" IS 'house | apartment | studio | townhouse | land | commercial. A physical classification, unlike the listing which is a commercial act.';
COMMENT ON COLUMN "properties"."bedrooms" IS 'Bedroom count. Null for land and most commercial units, which is why it is not mandatory.';
COMMENT ON COLUMN "properties"."bathrooms" IS 'Bathroom count, allowing halves, because a half bath is a real and advertised thing.';
COMMENT ON COLUMN "properties"."floor_area_sqm" IS 'Internal floor area in square metres. Stored in one unit and converted for display, so that sorting by size is not a per-country branch.';
COMMENT ON COLUMN "properties"."plot_area_sqm" IS 'Land area in square metres. Null for apartments.';
COMMENT ON COLUMN "properties"."year_built" IS 'Construction year. Null when unknown, which is common for older stock.';
COMMENT ON COLUMN "properties"."tenure" IS 'freehold | leasehold | commonhold | share_of_freehold. A property-level legal fact that outlives any particular sale.';
COMMENT ON COLUMN "properties"."energy_rating" IS 'Energy performance grade. Mandatory to publish in several jurisdictions, which is why it sits on the property and not the listing.';
COMMENT ON COLUMN "properties"."created_at" IS 'When the property first entered the portal.';

CREATE INDEX "idx_properties_area_type"
ON "properties" ("area_id", "property_type");
CREATE INDEX "idx_properties_latlng"
ON "properties" ("latitude", "longitude");
CREATE INDEX "idx_properties_postcode"
ON "properties" ("postcode");

CREATE TABLE IF NOT EXISTS "listings" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Property being marketed. Many listings over time point at the same row, which is exactly the point.
	"property_id" BIGINT NOT NULL,
	-- Agent responsible. Null while a listing is being prepared by the agency rather than an individual.
	"agent_id" BIGINT,
	-- Agency marketing it. Stored alongside the agent because the commercial relationship is with the agency and must survive the agent leaving.
	"agency_id" BIGINT NOT NULL,
	-- Public reference quoted in enquiries and printed on particulars. New for each campaign, unlike the property reference.
	"listing_reference" VARCHAR(32) NOT NULL UNIQUE,
	-- sale | rent. The same property is often listed for sale after a tenancy ends, which is a second listing rather than an edit.
	"listing_type" VARCHAR(16) NOT NULL DEFAULT 'sale',
	-- draft | live | under_offer | sold | let | withdrawn | expired. Terminal states are kept forever; relisting creates a new row.
	"status" VARCHAR(24) NOT NULL DEFAULT 'draft',
	-- Marketing title as written for this campaign. A relisting is usually rewritten, which is one more reason it is not a property column.
	"headline" VARCHAR(300) NOT NULL,
	-- Full marketing copy for this campaign.
	"description" TEXT,
	-- Current asking price in minor units. The history of what it used to be lives in listing_price_history.
	"asking_price_minor" BIGINT NOT NULL,
	-- ISO 4217 currency of the asking price.
	"currency_code" CHAR(3) NOT NULL,
	-- week | month | year, for rental listings. Null for sales. Without it a rent figure is uninterpretable.
	"rent_period" VARCHAR(16),
	-- Whether the price is hidden. The number is still stored, because range filters must keep working even when display is suppressed.
	"is_price_on_application" BOOLEAN NOT NULL DEFAULT false,
	-- Earliest occupation date, mostly for rentals.
	"available_from" DATE,
	-- When the listing went live. Null while a draft, and the field days-on-market counts from.
	"listed_at" TIMESTAMPTZ,
	-- When it left the market, whatever the reason. Together with listed_at this gives a clean campaign duration without inference from status changes.
	"delisted_at" TIMESTAMPTZ,
	-- sold | let | withdrawn | expired | duplicate. The reason a campaign ended is the single most useful input to a price-strategy report.
	"delist_reason" VARCHAR(24),
	-- Page views for this campaign, as a counter. Per-campaign rather than per-property, so a relisting starts honestly at zero.
	"view_count" INTEGER NOT NULL DEFAULT 0,
	-- Enquiries received. The ratio against view_count is what tells an agent the photographs are the problem.
	"enquiry_count" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "listings" IS 'One marketing campaign for one property. A property listed, withdrawn and relisted six months later at a lower price is three rows and two listings, which is what makes days-on-market, price strategy and relisting analysis answerable at all.';
COMMENT ON COLUMN "listings"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "listings"."property_id" IS 'Property being marketed. Many listings over time point at the same row, which is exactly the point.';
COMMENT ON COLUMN "listings"."agent_id" IS 'Agent responsible. Null while a listing is being prepared by the agency rather than an individual.';
COMMENT ON COLUMN "listings"."agency_id" IS 'Agency marketing it. Stored alongside the agent because the commercial relationship is with the agency and must survive the agent leaving.';
COMMENT ON COLUMN "listings"."listing_reference" IS 'Public reference quoted in enquiries and printed on particulars. New for each campaign, unlike the property reference.';
COMMENT ON COLUMN "listings"."listing_type" IS 'sale | rent. The same property is often listed for sale after a tenancy ends, which is a second listing rather than an edit.';
COMMENT ON COLUMN "listings"."status" IS 'draft | live | under_offer | sold | let | withdrawn | expired. Terminal states are kept forever; relisting creates a new row.';
COMMENT ON COLUMN "listings"."headline" IS 'Marketing title as written for this campaign. A relisting is usually rewritten, which is one more reason it is not a property column.';
COMMENT ON COLUMN "listings"."description" IS 'Full marketing copy for this campaign.';
COMMENT ON COLUMN "listings"."asking_price_minor" IS 'Current asking price in minor units. The history of what it used to be lives in listing_price_history.';
COMMENT ON COLUMN "listings"."currency_code" IS 'ISO 4217 currency of the asking price.';
COMMENT ON COLUMN "listings"."rent_period" IS 'week | month | year, for rental listings. Null for sales. Without it a rent figure is uninterpretable.';
COMMENT ON COLUMN "listings"."is_price_on_application" IS 'Whether the price is hidden. The number is still stored, because range filters must keep working even when display is suppressed.';
COMMENT ON COLUMN "listings"."available_from" IS 'Earliest occupation date, mostly for rentals.';
COMMENT ON COLUMN "listings"."listed_at" IS 'When the listing went live. Null while a draft, and the field days-on-market counts from.';
COMMENT ON COLUMN "listings"."delisted_at" IS 'When it left the market, whatever the reason. Together with listed_at this gives a clean campaign duration without inference from status changes.';
COMMENT ON COLUMN "listings"."delist_reason" IS 'sold | let | withdrawn | expired | duplicate. The reason a campaign ended is the single most useful input to a price-strategy report.';
COMMENT ON COLUMN "listings"."view_count" IS 'Page views for this campaign, as a counter. Per-campaign rather than per-property, so a relisting starts honestly at zero.';
COMMENT ON COLUMN "listings"."enquiry_count" IS 'Enquiries received. The ratio against view_count is what tells an agent the photographs are the problem.';

CREATE INDEX "idx_listings_status_type_listed"
ON "listings" ("status", "listing_type", "listed_at");
CREATE INDEX "idx_listings_property_listed"
ON "listings" ("property_id", "listed_at");
CREATE INDEX "idx_listings_agency_status"
ON "listings" ("agency_id", "status");

CREATE TABLE IF NOT EXISTS "listing_price_history" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Campaign whose price moved.
	"listing_id" BIGINT NOT NULL,
	-- Asking price in minor units as of this change.
	"price_minor" BIGINT NOT NULL,
	-- ISO 4217 currency, repeated per row because a rare currency redenomination must not rewrite history.
	"currency_code" CHAR(3) NOT NULL,
	-- initial | reduction | increase | correction. The first row of every listing is initial, so the sequence is complete rather than implying a starting point.
	"change_kind" VARCHAR(16) NOT NULL DEFAULT 'reduction',
	-- Agent who made the change. Null for automated imports from an agency feed.
	"changed_by_agent_id" BIGINT,
	-- When the new price took effect. Ordering by this reconstructs the full price path of the campaign.
	"effective_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Optional reason, usually recording that the vendor instructed the reduction rather than the agent proposing it.
	"note" VARCHAR(300),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "listing_price_history" IS 'Price as a sequence of dated rows. A reduction is the strongest buying signal a portal has and the main driver of alert emails, and neither is available if the previous price was overwritten.';
COMMENT ON COLUMN "listing_price_history"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "listing_price_history"."listing_id" IS 'Campaign whose price moved.';
COMMENT ON COLUMN "listing_price_history"."price_minor" IS 'Asking price in minor units as of this change.';
COMMENT ON COLUMN "listing_price_history"."currency_code" IS 'ISO 4217 currency, repeated per row because a rare currency redenomination must not rewrite history.';
COMMENT ON COLUMN "listing_price_history"."change_kind" IS 'initial | reduction | increase | correction. The first row of every listing is initial, so the sequence is complete rather than implying a starting point.';
COMMENT ON COLUMN "listing_price_history"."changed_by_agent_id" IS 'Agent who made the change. Null for automated imports from an agency feed.';
COMMENT ON COLUMN "listing_price_history"."effective_at" IS 'When the new price took effect. Ordering by this reconstructs the full price path of the campaign.';
COMMENT ON COLUMN "listing_price_history"."note" IS 'Optional reason, usually recording that the vendor instructed the reduction rather than the agent proposing it.';

CREATE INDEX "idx_price_history_listing_effective"
ON "listing_price_history" ("listing_id", "effective_at");

CREATE TABLE IF NOT EXISTS "listing_media" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Campaign the media belongs to. Tied to the listing rather than the property because each campaign is rephotographed, usually in a different season.
	"listing_id" BIGINT NOT NULL,
	-- photo | floorplan | video | virtual_tour | brochure. They render in different components, so the kind cannot be inferred from the file extension alone.
	"media_kind" VARCHAR(16) NOT NULL DEFAULT 'photo',
	-- Object storage key for the original. Derivatives are generated from it rather than stored as separate rows.
	"storage_key" VARCHAR(500) NOT NULL,
	-- Room label such as Kitchen or Rear garden. Used for accessibility text and for the gallery captions.
	"caption" VARCHAR(300),
	-- Display position within the gallery. Explicit because the order agents choose is a sales decision, and upload order is not it.
	"sort_order" INTEGER NOT NULL DEFAULT 0,
	-- Whether this is the search-result thumbnail. Exactly one per listing, enforced by a partial unique index in the physical schema.
	"is_primary" BOOLEAN NOT NULL DEFAULT false,
	-- Pixel width, stored so a layout can reserve space before the image loads.
	"width_px" INTEGER,
	-- Pixel height.
	"height_px" INTEGER,
	-- Upload time, used to spot listings running on photographs from a previous campaign.
	"uploaded_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "listing_media" IS 'Ordered gallery items. The explicit sort_order and single primary flag exist because the first photograph determines whether anyone clicks at all, and agents reorder deliberately.';
COMMENT ON COLUMN "listing_media"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "listing_media"."listing_id" IS 'Campaign the media belongs to. Tied to the listing rather than the property because each campaign is rephotographed, usually in a different season.';
COMMENT ON COLUMN "listing_media"."media_kind" IS 'photo | floorplan | video | virtual_tour | brochure. They render in different components, so the kind cannot be inferred from the file extension alone.';
COMMENT ON COLUMN "listing_media"."storage_key" IS 'Object storage key for the original. Derivatives are generated from it rather than stored as separate rows.';
COMMENT ON COLUMN "listing_media"."caption" IS 'Room label such as Kitchen or Rear garden. Used for accessibility text and for the gallery captions.';
COMMENT ON COLUMN "listing_media"."sort_order" IS 'Display position within the gallery. Explicit because the order agents choose is a sales decision, and upload order is not it.';
COMMENT ON COLUMN "listing_media"."is_primary" IS 'Whether this is the search-result thumbnail. Exactly one per listing, enforced by a partial unique index in the physical schema.';
COMMENT ON COLUMN "listing_media"."width_px" IS 'Pixel width, stored so a layout can reserve space before the image loads.';
COMMENT ON COLUMN "listing_media"."height_px" IS 'Pixel height.';
COMMENT ON COLUMN "listing_media"."uploaded_at" IS 'Upload time, used to spot listings running on photographs from a previous campaign.';

CREATE INDEX "idx_media_listing_order"
ON "listing_media" ("listing_id", "sort_order");

CREATE TABLE IF NOT EXISTS "features" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable machine code such as off_street_parking. Filters and saved searches reference this, so renaming the label never breaks a stored search.
	"code" VARCHAR(48) NOT NULL UNIQUE,
	-- Display text shown in the amenities list.
	"label" VARCHAR(120) NOT NULL,
	-- indoor | outdoor | parking | accessibility | utilities | general. Used to group the amenities panel rather than list forty items flat.
	"category" VARCHAR(40) NOT NULL DEFAULT 'general',
	-- Whether it appears as a search filter. Many features are worth displaying but too rare or too vague to filter on.
	"is_filterable" BOOLEAN NOT NULL DEFAULT true,
	-- Display order within the category, so that the amenities buyers care about are not alphabetically buried.
	"sort_order" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "features" IS 'A controlled vocabulary of amenities. Free-text bullet points are what make a portal unsearchable; codes are what let a saved search for a garden keep working after someone rewrites the label.';
COMMENT ON COLUMN "features"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "features"."code" IS 'Stable machine code such as off_street_parking. Filters and saved searches reference this, so renaming the label never breaks a stored search.';
COMMENT ON COLUMN "features"."label" IS 'Display text shown in the amenities list.';
COMMENT ON COLUMN "features"."category" IS 'indoor | outdoor | parking | accessibility | utilities | general. Used to group the amenities panel rather than list forty items flat.';
COMMENT ON COLUMN "features"."is_filterable" IS 'Whether it appears as a search filter. Many features are worth displaying but too rare or too vague to filter on.';
COMMENT ON COLUMN "features"."sort_order" IS 'Display order within the category, so that the amenities buyers care about are not alphabetically buried.';

CREATE TABLE IF NOT EXISTS "property_features" (
	-- Property that has the feature. Half of the composite key, so there is no surrogate id to add nothing.
	"property_id" BIGINT,
	-- Feature present. Together with property_id this makes double-tagging impossible.
	"feature_id" BIGINT,
	-- Qualifier such as two spaces or south facing. The feature says what, this says how much, without needing a column per amenity.
	"detail" VARCHAR(160),
	-- When an agent confirmed the feature at a physical visit. Null means it came from a vendor questionnaire, which is a materially weaker claim.
	"verified_at" TIMESTAMPTZ,
	PRIMARY KEY("property_id", "feature_id")
);

COMMENT ON TABLE "property_features" IS 'Many-to-many between properties and amenities. It hangs off the property rather than the listing because a garden does not disappear when a campaign ends, and a relisting should inherit the tags.';
COMMENT ON COLUMN "property_features"."property_id" IS 'Property that has the feature. Half of the composite key, so there is no surrogate id to add nothing.';
COMMENT ON COLUMN "property_features"."feature_id" IS 'Feature present. Together with property_id this makes double-tagging impossible.';
COMMENT ON COLUMN "property_features"."detail" IS 'Qualifier such as two spaces or south facing. The feature says what, this says how much, without needing a column per amenity.';
COMMENT ON COLUMN "property_features"."verified_at" IS 'When an agent confirmed the feature at a physical visit. Null means it came from a vendor questionnaire, which is a materially weaker claim.';

CREATE TABLE IF NOT EXISTS "contacts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity and the address alerts are sent to.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name given at registration. Null for an account created by a one-click enquiry, which is a legitimate half-registered state.
	"full_name" VARCHAR(200),
	-- Number agents call back on. Its presence is the strongest predictor of a serious enquiry.
	"phone" VARCHAR(32),
	-- buyer | tenant | vendor | landlord. The same person is often two of these at once, and the value records what brought them in.
	"contact_kind" VARCHAR(16) NOT NULL DEFAULT 'buyer',
	-- Area they mostly browse, cached from behaviour to seed a new saved search.
	"preferred_area_id" BIGINT,
	-- Self-declared ceiling in minor units. Used to sort alerts, never to hide listings, because stated budgets are aspirational.
	"budget_max_minor" BIGINT,
	-- ISO 4217 currency of the budget.
	"currency_code" CHAR(3),
	-- Consent for non-transactional email, defaulting to false because the regulator requires opt-in rather than opt-out.
	"marketing_opt_in" BOOLEAN NOT NULL DEFAULT false,
	-- Registration time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "contacts" IS 'The demand side. Kept apart from agents because a person can be both, and because nothing on this row should ever grant access to an agency dashboard.';
COMMENT ON COLUMN "contacts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "contacts"."email" IS 'Login identity and the address alerts are sent to.';
COMMENT ON COLUMN "contacts"."full_name" IS 'Name given at registration. Null for an account created by a one-click enquiry, which is a legitimate half-registered state.';
COMMENT ON COLUMN "contacts"."phone" IS 'Number agents call back on. Its presence is the strongest predictor of a serious enquiry.';
COMMENT ON COLUMN "contacts"."contact_kind" IS 'buyer | tenant | vendor | landlord. The same person is often two of these at once, and the value records what brought them in.';
COMMENT ON COLUMN "contacts"."preferred_area_id" IS 'Area they mostly browse, cached from behaviour to seed a new saved search.';
COMMENT ON COLUMN "contacts"."budget_max_minor" IS 'Self-declared ceiling in minor units. Used to sort alerts, never to hide listings, because stated budgets are aspirational.';
COMMENT ON COLUMN "contacts"."currency_code" IS 'ISO 4217 currency of the budget.';
COMMENT ON COLUMN "contacts"."marketing_opt_in" IS 'Consent for non-transactional email, defaulting to false because the regulator requires opt-in rather than opt-out.';
COMMENT ON COLUMN "contacts"."created_at" IS 'Registration time.';

CREATE TABLE IF NOT EXISTS "viewings" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Campaign the viewing is against. Tied to the listing rather than the property so that viewings from a previous campaign do not inflate this one.
	"listing_id" BIGINT NOT NULL,
	-- Prospective buyer or tenant attending.
	"contact_id" BIGINT NOT NULL,
	-- Agent conducting it. Null for an open house, where attendance is recorded but no individual is assigned.
	"agent_id" BIGINT,
	-- in_person | virtual | open_house. Virtual viewings convert differently and are worth separating from the start.
	"viewing_kind" VARCHAR(16) NOT NULL DEFAULT 'in_person',
	-- Appointment start in absolute time, with the property timezone applied at display.
	"scheduled_at" TIMESTAMPTZ NOT NULL,
	-- Planned length, used for calendar blocking and to stop double-booking an agent.
	"duration_minutes" SMALLINT NOT NULL DEFAULT 30,
	-- requested | confirmed | completed | cancelled | no_show. No-show is its own value because it is an agent-side metric, not a synonym for cancelled.
	"status" VARCHAR(24) NOT NULL DEFAULT 'requested',
	-- Why it fell through. Mostly used to tell vendor cancellations apart from buyer ones.
	"cancelled_reason" VARCHAR(200),
	-- Post-viewing feedback, which the vendor is contractually entitled to see in many jurisdictions.
	"feedback" TEXT,
	-- One to five interest score recorded by the agent. A number so that a vendor report can average it.
	"feedback_rating" SMALLINT,
	-- When the appointment was requested.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "viewings" IS 'One appointment. It is the bridge between browsing and buying, and the count of these per listing is the honest measure of whether a price is right, long before any offer arrives.';
COMMENT ON COLUMN "viewings"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "viewings"."listing_id" IS 'Campaign the viewing is against. Tied to the listing rather than the property so that viewings from a previous campaign do not inflate this one.';
COMMENT ON COLUMN "viewings"."contact_id" IS 'Prospective buyer or tenant attending.';
COMMENT ON COLUMN "viewings"."agent_id" IS 'Agent conducting it. Null for an open house, where attendance is recorded but no individual is assigned.';
COMMENT ON COLUMN "viewings"."viewing_kind" IS 'in_person | virtual | open_house. Virtual viewings convert differently and are worth separating from the start.';
COMMENT ON COLUMN "viewings"."scheduled_at" IS 'Appointment start in absolute time, with the property timezone applied at display.';
COMMENT ON COLUMN "viewings"."duration_minutes" IS 'Planned length, used for calendar blocking and to stop double-booking an agent.';
COMMENT ON COLUMN "viewings"."status" IS 'requested | confirmed | completed | cancelled | no_show. No-show is its own value because it is an agent-side metric, not a synonym for cancelled.';
COMMENT ON COLUMN "viewings"."cancelled_reason" IS 'Why it fell through. Mostly used to tell vendor cancellations apart from buyer ones.';
COMMENT ON COLUMN "viewings"."feedback" IS 'Post-viewing feedback, which the vendor is contractually entitled to see in many jurisdictions.';
COMMENT ON COLUMN "viewings"."feedback_rating" IS 'One to five interest score recorded by the agent. A number so that a vendor report can average it.';
COMMENT ON COLUMN "viewings"."created_at" IS 'When the appointment was requested.';

CREATE INDEX "idx_viewings_listing_time"
ON "viewings" ("listing_id", "scheduled_at");
CREATE INDEX "idx_viewings_agent_time"
ON "viewings" ("agent_id", "scheduled_at");
CREATE INDEX "idx_viewings_contact_status"
ON "viewings" ("contact_id", "status");

CREATE TABLE IF NOT EXISTS "offers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Campaign the offer is against.
	"listing_id" BIGINT NOT NULL,
	-- Party making the offer.
	"contact_id" BIGINT NOT NULL,
	-- Offered amount in minor units. Never overwritten: a counter-offer is a new row referencing this one.
	"amount_minor" BIGINT NOT NULL,
	-- ISO 4217 currency of the offer.
	"currency_code" CHAR(3) NOT NULL,
	-- submitted | under_review | accepted | rejected | withdrawn | superseded | fell_through. Fell through is separate from rejected because it happens after acceptance and behaves completely differently.
	"status" VARCHAR(24) NOT NULL DEFAULT 'submitted',
	-- Previous offer in the negotiation. Chaining rows gives the full back-and-forth, which is what both sides argue about later.
	"supersedes_offer_id" BIGINT,
	-- Whether the buyer has nothing to sell first. Null when unknown, and it routinely beats a higher offer that comes with a chain.
	"is_chain_free" BOOLEAN,
	-- cash | mortgage_agreed | mortgage_in_principle | unknown. Alongside chain status, this is how a vendor compares two offers that are not simply two numbers.
	"funding_kind" VARCHAR(24),
	-- Conditions attached, such as a survey or a fixtures list. Free text because they are genuinely arbitrary.
	"conditions" TEXT,
	-- When it was received. Ties in ordering are broken by this, and the sequence matters in a sealed-bid process.
	"submitted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the vendor decision was recorded. Null while pending.
	"responded_at" TIMESTAMPTZ,
	-- When the offer lapses if unanswered. Null means open-ended, which is the default in most markets.
	"expires_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "offers" IS 'Append-only negotiation history. Every offer, counter and withdrawal is a row, because the interesting questions — how far below asking, how many rounds, how often a chain-free bid wins — are all questions about the sequence.';
COMMENT ON COLUMN "offers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "offers"."listing_id" IS 'Campaign the offer is against.';
COMMENT ON COLUMN "offers"."contact_id" IS 'Party making the offer.';
COMMENT ON COLUMN "offers"."amount_minor" IS 'Offered amount in minor units. Never overwritten: a counter-offer is a new row referencing this one.';
COMMENT ON COLUMN "offers"."currency_code" IS 'ISO 4217 currency of the offer.';
COMMENT ON COLUMN "offers"."status" IS 'submitted | under_review | accepted | rejected | withdrawn | superseded | fell_through. Fell through is separate from rejected because it happens after acceptance and behaves completely differently.';
COMMENT ON COLUMN "offers"."supersedes_offer_id" IS 'Previous offer in the negotiation. Chaining rows gives the full back-and-forth, which is what both sides argue about later.';
COMMENT ON COLUMN "offers"."is_chain_free" IS 'Whether the buyer has nothing to sell first. Null when unknown, and it routinely beats a higher offer that comes with a chain.';
COMMENT ON COLUMN "offers"."funding_kind" IS 'cash | mortgage_agreed | mortgage_in_principle | unknown. Alongside chain status, this is how a vendor compares two offers that are not simply two numbers.';
COMMENT ON COLUMN "offers"."conditions" IS 'Conditions attached, such as a survey or a fixtures list. Free text because they are genuinely arbitrary.';
COMMENT ON COLUMN "offers"."submitted_at" IS 'When it was received. Ties in ordering are broken by this, and the sequence matters in a sealed-bid process.';
COMMENT ON COLUMN "offers"."responded_at" IS 'When the vendor decision was recorded. Null while pending.';
COMMENT ON COLUMN "offers"."expires_at" IS 'When the offer lapses if unanswered. Null means open-ended, which is the default in most markets.';

CREATE INDEX "idx_offers_listing_submitted"
ON "offers" ("listing_id", "submitted_at");
CREATE INDEX "idx_offers_contact_status"
ON "offers" ("contact_id", "status");

CREATE TABLE IF NOT EXISTS "saved_searches" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner of the search.
	"contact_id" BIGINT NOT NULL,
	-- Label chosen by the user, such as Two beds near the park. Null for a search saved with one click from a results page.
	"name" VARCHAR(160),
	-- The full filter set: area ids, price range, bedrooms, feature codes, property types. Semi-structured because filters are added constantly and each new one would otherwise be a migration plus a backfill.
	"criteria" JSONB NOT NULL,
	-- Primary area, lifted out of the criteria so that the common case — new listings in this area — is an indexed lookup instead of a JSON scan.
	"area_id" BIGINT,
	-- sale | rent. Also lifted out of criteria, for the same reason: every match query filters on it.
	"listing_type" VARCHAR(16) NOT NULL DEFAULT 'sale',
	-- Lower bound in minor units. Null means unbounded below.
	"min_price_minor" BIGINT,
	-- Upper bound in minor units. Null means unbounded above, which is rarer than it sounds.
	"max_price_minor" BIGINT,
	-- instant | daily | weekly | off. Instant alerts exist because a price reduction is worth minutes, not a day.
	"alert_frequency" VARCHAR(16) NOT NULL DEFAULT 'daily',
	-- email | push | both. Stored per search, since people want instant push for one area and a weekly digest for another.
	"alert_channel" VARCHAR(16) NOT NULL DEFAULT 'email',
	-- When an alert was last sent. The alert job selects listings changed since this value, which is what stops the same property arriving twice.
	"last_alerted_at" TIMESTAMPTZ,
	-- Matches at the last run, so a digest can say how many are new rather than repeating the whole result set.
	"last_match_count" INTEGER NOT NULL DEFAULT 0,
	-- Paused searches stay as rows because people come back to the market after a year away.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- When the search was saved.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "saved_searches" IS 'A standing query with a delivery schedule. Denormalising area, type and price bounds out of the JSON criteria is deliberate: the alert job runs every saved search against every new listing, and that join has to be indexable.';
COMMENT ON COLUMN "saved_searches"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "saved_searches"."contact_id" IS 'Owner of the search.';
COMMENT ON COLUMN "saved_searches"."name" IS 'Label chosen by the user, such as Two beds near the park. Null for a search saved with one click from a results page.';
COMMENT ON COLUMN "saved_searches"."criteria" IS 'The full filter set: area ids, price range, bedrooms, feature codes, property types. Semi-structured because filters are added constantly and each new one would otherwise be a migration plus a backfill.';
COMMENT ON COLUMN "saved_searches"."area_id" IS 'Primary area, lifted out of the criteria so that the common case — new listings in this area — is an indexed lookup instead of a JSON scan.';
COMMENT ON COLUMN "saved_searches"."listing_type" IS 'sale | rent. Also lifted out of criteria, for the same reason: every match query filters on it.';
COMMENT ON COLUMN "saved_searches"."min_price_minor" IS 'Lower bound in minor units. Null means unbounded below.';
COMMENT ON COLUMN "saved_searches"."max_price_minor" IS 'Upper bound in minor units. Null means unbounded above, which is rarer than it sounds.';
COMMENT ON COLUMN "saved_searches"."alert_frequency" IS 'instant | daily | weekly | off. Instant alerts exist because a price reduction is worth minutes, not a day.';
COMMENT ON COLUMN "saved_searches"."alert_channel" IS 'email | push | both. Stored per search, since people want instant push for one area and a weekly digest for another.';
COMMENT ON COLUMN "saved_searches"."last_alerted_at" IS 'When an alert was last sent. The alert job selects listings changed since this value, which is what stops the same property arriving twice.';
COMMENT ON COLUMN "saved_searches"."last_match_count" IS 'Matches at the last run, so a digest can say how many are new rather than repeating the whole result set.';
COMMENT ON COLUMN "saved_searches"."is_active" IS 'Paused searches stay as rows because people come back to the market after a year away.';
COMMENT ON COLUMN "saved_searches"."created_at" IS 'When the search was saved.';

CREATE INDEX "idx_saved_searches_contact_active"
ON "saved_searches" ("contact_id", "is_active");
CREATE INDEX "idx_saved_searches_alert_due"
ON "saved_searches" ("alert_frequency", "last_alerted_at");

